                // "Drum & Bass" -> "drumbass", "drum and bass" -> "drumandbass" (both are registered), "Lo-fi" -> "lofi"
                inline std::string normalize_name(const std::string& s) {
                    std::string o; for (char c : s) if (std::isalnum(static_cast<unsigned char>(c))) o += static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
                    return o;
                }
